+// API keys and roles. Keys live in the data (`apiKeys`); see docs/API.md.
+import { AppError } from "../errors.js";
+
+const COOK = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The key record for an Authorization header, or throws unauthorized. */
+export function authenticate(store, headers) {
+  const h = Object.entries(headers).find(([k]) => k.toLowerCase() === "authorization")?.[1];
+  const m = /^Bearer (.+)$/.exec(typeof h === "string" ? h : "");
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws forbidden unless `role` may make this request. */
+export function authorize(role, method, path) {
+  if (role === "manager") return;
+  if (path === "/audit") throw new AppError("forbidden");
+  if (method === "GET") return;
+  if (role === "cook" && COOK.some(([m, re]) => m === method && re.test(path))) return;
+  throw new AppError("forbidden");
+}
