@@ -0,0 +1,33 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const a = await raw({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  assert.equal((await raw({ path: "/items", headers: { authorization: "Bearer nope" } })).status, 401);
+});
+
+test("viewers read only; cooks cook but do not start stock-takes", async () => {
+  const viewer = app(undefined, "viewer");
+  assert.equal((await viewer.handle({ path: "/items" })).status, 200);
+  const r = await viewer.handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(r.status, 403);
+  assert.equal(r.body.error.code, "forbidden");
+  assert.equal((await viewer.handle({ path: "/audit" })).status, 403);
+  const cook = app(undefined, "cook");
+  assert.equal((await cook.handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await cook.handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+});
+
+test("changes are audited and listed newest first for managers", async () => {
+  const { handle } = app(undefined, "manager");
+  await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await handle({ method: "POST", path: "/recipes/2/cook", body: { portions: 100 } });
+  const log = (await handle({ path: "/audit" })).body;
+  assert.equal(log.length, 2);
+  assert.deepEqual([log[0].status, log[0].path, log[0].key, log[0].method], [409, "/recipes/2/cook", "manager", "POST"]);
+  assert.equal(log[1].status, 200);
+});
